    },
    price: {
      type: Number,
      required: true,
      min: 0,
    },
    currency: {
      type: String,
      default: 'eur',
      lowercase: true,
      trim: true,
    },
    marketplace: {
      type: Number,
      required: true,
      min: 0,

    },
    request_quota: {
      type: Number,
      required: true,
      min: 0,

    },
    expireAt: {
      type: Date,
      default: null,
    },
    billingCycle: {
      type: Number,
      enum: [1, 2, 3], // 1 = Monthly, 2 = Quarterly, 3 = Yearly
