const passport = require('passport');
const httpStatus = require('http-status');
const ApiError = require('../utils/ApiError');
const { roleRights } = require('../config/roles');

const verifyCallback =
  (req, resolve, reject, requiredRights) => async (err, user, info) => {
    if (err || info || !user) {
      return reject(
        new ApiError(httpStatus.UNAUTHORIZED, 'Please authenticate')
      );
    }
    req.user = user;

    if (requiredRights.length) {
      const userRights = roleRights.get(user.role);
      const hasRequiredRights = requiredRights.every((requiredRight) =>
        userRights.includes(requiredRight)
      );
      if (!hasRequiredRights && req.params.userId !== user.id) {
        return reject(
          new ApiError(
            httpStatus.FORBIDDEN,
            'You do not have permission to access this resource.'
          )
        );
      }
    }

    resolve();
  };

const auth =
  (...requiredRights) =>
  async (req, res, next) => {
    return new Promise((resolve, reject) => {
      passport.authenticate(
        'jwt',
        { session: false },
        verifyCallback(req, resolve, reject, requiredRights)
      )(req, res, next);
    })
      .then(() => next())
      .catch((err) => next(err));
  };

module.exports = auth;

const httpStatus = require('http-status');
const ApiError = require('../utils/ApiError');
const {
  getPermissionsForUser,
  can,
  isSellerOwner,
} = require('../services/permission.service');

const hasBypassForSection = (user, section) => {
  if (!user) return false;
  if (user.isSuperAdmin) {
    return true;
  }
  if (user.userType !== 'admin' && isSellerOwner(user)) {
    return true;
  }
  return false;
};

/**
 * Require a section action permission.
 * SuperAdmin and sellerAdmin bypass checks (sellerAdmin only for seller sections).
 *
 * @param {string} section
 * @param {'view'|'create'|'update'|'delete'} action
 */
const requirePermission =
  (section, action = 'view') =>
    async (req, res, next) => {
      try {
        if (!req.user) {
          return next(new ApiError(httpStatus.UNAUTHORIZED, 'Please authenticate'));
        }

        if (req.user.isSuperAdmin || hasBypassForSection(req.user, section)) {
          return next();
        }

        const { permissions } = await getPermissionsForUser(req.user);
        req.permissions = permissions;

        if (!can(permissions, section, action)) {
          return next(
            new ApiError(
              httpStatus.FORBIDDEN,
              `You do not have permission to perform this action (${section}.${action}).`
            )
          );
        }

        return next();
      } catch (error) {
        return next(error);
      }
    };

/**
 * Allow access when the user matches ANY of the given section/action pairs.
 * Useful for role dropdowns needed while creating/updating users.
 *
 * @param {Array<[string, string]>} requirements
 */
const requireAnyPermission =
  (requirements = []) =>
    async (req, res, next) => {
      try {
        if (!req.user) {
          return next(new ApiError(httpStatus.UNAUTHORIZED, 'Please authenticate'));
        }

        if (req.user.isSuperAdmin) {
          return next();
        }

        for (const [section] of requirements) {
          if (hasBypassForSection(req.user, section)) {
            return next();
          }
        }

        const { permissions } = await getPermissionsForUser(req.user);
        req.permissions = permissions;

        const allowed = requirements.some(([section, action]) =>
          can(permissions, section, action)
        );

        if (!allowed) {
          const label = requirements
            .map(([section, action]) => `${section}.${action}`)
            .join(' | ');
          return next(
            new ApiError(
              httpStatus.FORBIDDEN,
              `You do not have permission to perform this action (${label}).`
            )
          );
        }

        return next();
      } catch (error) {
        return next(error);
      }
    };

module.exports = requirePermission;
module.exports.requirePermission = requirePermission;
module.exports.requireAnyPermission = requireAnyPermission;

